import MailParser from './mail-parser.js';
function simpleParser(input, options, callback) {
    if (input === null || input === undefined) {
        throw new TypeError('Input cannot be null or undefined.');
    }
    if (!callback && typeof options === 'function') {
        callback = options;
        options = false;
    }
    let promise;
    let done;
    if (!callback) {
        promise = new Promise((resolve, reject) => {
            done = (err, mail) => {
                if (err) {
                    reject(err);
                }
                else {
                    resolve(mail);
                }
            };
        });
    }
    else {
        done = callback;
    }
    // MailParser may emit a non-fatal 'error' and still reach 'end', so settle only once:
    // the first error or the result wins
    let settled = false;
    let settle = (...args) => {
        if (settled) {
            return;
        }
        settled = true;
        done(...args);
    };
    let parserOptions = options || {};
    let keepCidLinks = !!parserOptions.keepCidLinks;
    let mail = {
        attachments: []
    };
    let parser = new MailParser(parserOptions);
    parser.on('error', err => {
        settle(err);
    });
    parser.on('headers', headers => {
        mail.headers = headers;
        mail.headerLines = parser.headerLines;
        if (parser.otp) {
            mail.otp = parser.otp;
        }
    });
    let reading = false;
    let reader = () => {
        reading = true;
        let data = parser.read();
        if (data === null) {
            reading = false;
            return;
        }
        if (data.type === 'text') {
            Object.keys(data).forEach(key => {
                if (['text', 'html', 'textAsHtml', 'textConversionError'].includes(key)) {
                    mail[key] = data[key];
                }
            });
        }
        if (data.type === 'attachment') {
            let attachment = data;
            mail.attachments.push(attachment);
            let chunks = [];
            let chunklen = 0;
            attachment.content.on('readable', () => {
                let chunk;
                while ((chunk = attachment.content.read()) !== null) {
                    chunks.push(chunk);
                    chunklen += chunk.length;
                }
            });
            attachment.content.on('end', () => {
                attachment.content = Buffer.concat(chunks, chunklen);
                attachment.release();
                reader();
            });
        }
        else {
            reader();
        }
    };
    parser.on('readable', () => {
        if (!reading) {
            reader();
        }
    });
    parser.on('end', () => {
        ['subject', 'references', 'date', 'to', 'from', 'to', 'cc', 'bcc', 'message-id', 'in-reply-to', 'reply-to'].forEach(key => {
            if (mail.headers && mail.headers.has(key)) {
                mail[key.replace(/-([a-z])/g, (m, c) => c.toUpperCase())] = mail.headers.get(key);
            }
        });
        if (keepCidLinks) {
            return settle(null, mail);
        }
        parser.updateImageLinks((attachment, done) => done(false, 'data:' + attachment.contentType + ';base64,' + attachment.content.toString('base64')), (err, html) => {
            if (err) {
                return settle(err);
            }
            mail.html = html;
            settle(null, mail);
        });
    });
    if (typeof input === 'string') {
        parser.end(Buffer.from(input));
    }
    else if (Buffer.isBuffer(input)) {
        parser.end(input);
    }
    else {
        input
            .once('error', err => {
            input.destroy();
            parser.destroy();
            settle(err);
        })
            .pipe(parser);
    }
    return promise;
}
export default simpleParser;
